type Response = {ok: true; value: unknown} | {ok: false; error: string};
export async function retrySimulatedRequest(responses: Response[], maxAttempts: number): Promise<unknown> {
  if (!Number.isInteger(maxAttempts) || maxAttempts < 1) throw new Error('Invalid attempts');
  for (let i = 0; i < maxAttempts; i++) {
    if (i >= responses.length) throw new Error('No response');
    const response = responses[i];
    try {
      const value = await (response.ok ? Promise.resolve(response.value) : Promise.reject(new Error(response.error)));
      return { value, attemptsUsed: i + 1 };
    } catch (error) {
      if (i === maxAttempts - 1) throw error;
    }
  }
  throw new Error('No response');
}
